#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdlib>
#include <cstdio>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <vector>

#include <omp.h>
#include <sched.h>

#ifdef STREAM_RUN_INFO
#include "../polus_numa/run_info.h"
#endif

using Clock = std::chrono::steady_clock;

constexpr double TARGET_SECONDS = 2.0;
constexpr long long ELEMENTS_PER_BLOCK = 16;
constexpr std::size_t MEMORY_ALIGNMENT = 128;
constexpr double SCALE_FACTOR = 3.0;
constexpr double BYTES_IN_GB = 1000000000.0;
constexpr double CHECK_ERROR = 0.000001;
constexpr int KERNEL_COUNT = 4;
constexpr int COPY = 0;
constexpr int SCALE = 1;
constexpr int ADD = 2;
constexpr int TRIAD = 3;
constexpr int OUTPUT_PRECISION = 6;

#if defined(__GNUC__) || defined(__clang__)
#define STREAM_RESTRICT __restrict__
#else
#define STREAM_RESTRICT __restrict
#endif

// Не даёт компилятору удалить одинаковые повторения цикла.
void compiler_barrier() {
    std::atomic_signal_fence(std::memory_order_seq_cst);
}

// Закрепляет текущий поток за выбранным логическим процессором.
void bind_thread(const std::vector<int>& thread_cpus) {
    int thread = omp_get_thread_num();
    if (omp_get_num_threads() != (int)thread_cpus.size()) {
        std::fprintf(stderr, "Unexpected OpenMP team size\n");
        std::exit(2);
    }
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(thread_cpus[thread], &set);
    if (sched_setaffinity(0, sizeof(set), &set) != 0) {
        std::perror("sched_setaffinity");
        std::exit(2);
    }
}

// Читает переданный Python список логических процессоров.
std::vector<int> read_cpus(const char* text) {
    std::vector<int> thread_cpus;
    std::stringstream input(text);
    std::string value;
    while (std::getline(input, value, ','))
        thread_cpus.push_back(std::atoi(value.c_str()));
    return thread_cpus;
}

void copy_kernel(const double* STREAM_RESTRICT a, double* STREAM_RESTRICT c, long long n, int repeats) {
    for (int repeat = 0; repeat < repeats; repeat++) {
        for (long long i = 0; i < n; i++) c[i] = a[i];
        compiler_barrier();
    }
}

void scale_kernel(const double* STREAM_RESTRICT c, double* STREAM_RESTRICT b, long long n, int repeats) {
    for (int repeat = 0; repeat < repeats; repeat++) {
        for (long long i = 0; i < n; i++) b[i] = SCALE_FACTOR * c[i];
        compiler_barrier();
    }
}

void add_kernel(const double* STREAM_RESTRICT a, const double* STREAM_RESTRICT b,
                double* STREAM_RESTRICT c, long long n, int repeats) {
    for (int repeat = 0; repeat < repeats; repeat++) {
        for (long long i = 0; i < n; i++) c[i] = a[i] + b[i];
        compiler_barrier();
    }
}

void triad_kernel(const double* STREAM_RESTRICT b, const double* STREAM_RESTRICT c,
                  double* STREAM_RESTRICT a, long long n, int repeats) {
    for (int repeat = 0; repeat < repeats; repeat++) {
        for (long long i = 0; i < n; i++) a[i] = b[i] + SCALE_FACTOR * c[i];
        compiler_barrier();
    }
}

// Выполняет выбранную операцию.
void stream_kernel(int kernel, double* a, double* b, double* c, long long n,
                   int repeats, const std::vector<int>& thread_cpus) {
#pragma omp parallel
    {
        bind_thread(thread_cpus);
        int thread = omp_get_thread_num();
        int threads = omp_get_num_threads();
        long long blocks = (n + ELEMENTS_PER_BLOCK - 1) / ELEMENTS_PER_BLOCK;
        long long begin = std::min(
            n, blocks * thread / threads * ELEMENTS_PER_BLOCK);
        long long end = std::min(
            n, blocks * (thread + 1) / threads * ELEMENTS_PER_BLOCK);
        long long count = end - begin;

        if (kernel == COPY) copy_kernel(a + begin, c + begin, count, repeats);
        if (kernel == SCALE) scale_kernel(c + begin, b + begin, count, repeats);
        if (kernel == ADD) add_kernel(a + begin, b + begin, c + begin, count, repeats);
        if (kernel == TRIAD) triad_kernel(b + begin, c + begin, a + begin, count, repeats);
    }
}

// Измеряет операцию.
void measure(int kernel, double* a, double* b, double* c, long long n,
             int repeats, int min_samples, int bytes, int& samples,
             double& total, double& median_time, double& best_time,
             double& median, double& best,
             const std::vector<int>& thread_cpus) {
    stream_kernel(kernel, a, b, c, n, 1, thread_cpus);
    std::vector<double> rates;
    std::vector<double> times;
    total = 0.0;
    while ((int)rates.size() < min_samples || total < TARGET_SECONDS) {
        Clock::time_point start = Clock::now();
        stream_kernel(kernel, a, b, c, n, repeats, thread_cpus);
        Clock::time_point finish = Clock::now();

        double seconds = std::chrono::duration<double>(finish - start).count();
        double speed = (double)bytes * n * repeats / seconds / BYTES_IN_GB;
        rates.push_back(speed);
        times.push_back(seconds);
        total += seconds;
    }

    std::sort(rates.begin(), rates.end());
    std::sort(times.begin(), times.end());
    samples = (int)rates.size();
    median = rates[rates.size() / 2];
    median_time = times[times.size() / 2];
    if (rates.size() % 2 == 0) {
        median = (median + rates[rates.size() / 2 - 1]) / 2.0;
        median_time = (median_time + times[times.size() / 2 - 1]) / 2.0;
    }
    best = rates.back();
    best_time = times.front();
}

// Создаёт массивы, запускает тесты и печатает CSV.
int main(int argc, char* argv[]) {
    if (argc != 6) {
        std::fprintf(stderr, "Usage: stream N threads samples repeats cpu_list\n");
        return 2;
    }
    long long n = std::atoll(argv[1]);
    int threads = std::atoi(argv[2]);
    int min_samples = std::atoi(argv[3]);
    int repeats = std::atoi(argv[4]);
    std::vector<int> thread_cpus = read_cpus(argv[5]);
    if (n <= 0 || threads <= 0 || min_samples <= 0 || repeats <= 0 ||
        (int)thread_cpus.size() != threads) return 2;
    for (int cpu : thread_cpus)
        if (cpu < 0 || cpu >= CPU_SETSIZE) return 2;
    omp_set_dynamic(0);
    omp_set_num_threads(threads);

    double* a;
    double* b;
    double* c;
    if (posix_memalign((void**)&a, MEMORY_ALIGNMENT, n * sizeof(double)) != 0 ||
        posix_memalign((void**)&b, MEMORY_ALIGNMENT, n * sizeof(double)) != 0 ||
        posix_memalign((void**)&c, MEMORY_ALIGNMENT, n * sizeof(double)) != 0) {
        std::fprintf(stderr, "Cannot allocate STREAM arrays\n");
        return 2;
    }

#pragma omp parallel
    {
        bind_thread(thread_cpus);
        int thread = omp_get_thread_num();
        int threads = omp_get_num_threads();
        long long blocks = (n + ELEMENTS_PER_BLOCK - 1) / ELEMENTS_PER_BLOCK;
        long long begin = std::min(
            n, blocks * thread / threads * ELEMENTS_PER_BLOCK);
        long long end = std::min(
            n, blocks * (thread + 1) / threads * ELEMENTS_PER_BLOCK);
        for (long long i = begin; i < end; i++) {
            a[i] = 1.0;
            b[i] = 2.0;
            c[i] = 0.0;
        }
    }
#ifdef STREAM_RUN_INFO
    stream_run_info(a, b, c, n, thread_cpus);
#endif
    const char* names[KERNEL_COUNT] = {"Copy", "Scale", "Add", "Triad"};
    int bytes[KERNEL_COUNT] = {
        2 * sizeof(double), 2 * sizeof(double),
        3 * sizeof(double), 3 * sizeof(double)
    };
    int samples[KERNEL_COUNT];
    double total[KERNEL_COUNT], median_time[KERNEL_COUNT];
    double best_time[KERNEL_COUNT], median[KERNEL_COUNT], best[KERNEL_COUNT];
    for (int kernel = 0; kernel < KERNEL_COUNT; kernel++)
        measure(kernel, a, b, c, n, repeats, min_samples, bytes[kernel],
                samples[kernel], total[kernel], median_time[kernel],
                best_time[kernel], median[kernel], best[kernel], thread_cpus);

    for (long long i = 0; i < n; i++) {
        if (std::abs(a[i] - 15.0) > CHECK_ERROR) return 1;
        if (std::abs(b[i] - SCALE_FACTOR) > CHECK_ERROR) return 1;
        if (std::abs(c[i] - 4.0) > CHECK_ERROR) return 1;
    }
    std::cout << "kernel,n,threads,bytes_per_element,repeats,samples,processed_gb,"
                 "measurement_seconds,median_seconds,best_seconds,"
                 "median_gbps,best_gbps\n";
    std::cout << std::fixed << std::setprecision(OUTPUT_PRECISION);
    for (int kernel = 0; kernel < KERNEL_COUNT; kernel++) {
        double data_gb = (double)bytes[kernel] * n * repeats
                         * samples[kernel] / BYTES_IN_GB;
        std::cout << names[kernel] << ',' << n << ',' << threads << ','
                  << bytes[kernel] << ',' << repeats << ',' << samples[kernel]
                  << ',' << data_gb << ',' << total[kernel] << ','
                  << median_time[kernel] << ',' << best_time[kernel] << ','
                  << median[kernel] << ',' << best[kernel] << '\n';
    }
    free(a);
    free(b);
    free(c);
    return 0;
}

